#include <bits/stdc++.h>
using namespace std;
int main(){
    int m;
    cin >> m;
    cin.ignore();
    while(m--){
        string line;
        getline(cin, line);
        istringstream iss(line);
        vector<int> w;
        int x;
        while(iss >> x) w.push_back(x);
        int total = accumulate(w.begin(), w.end(), 0);
        if (total % 2 != 0) { cout << "NO\n"; continue; }
        int half = total/2;
        vector<char> dp(half+1, 0);
        dp[0] = 1;
        for (int wi : w) {
            for (int s = half; s >= wi; s--) {
                if (dp[s-wi]) dp[s] = 1;
            }
        }
        cout << (dp[half] ? "YES" : "NO") << "\n";
    }
}

